-- Provider-neutral schema contract used by the base store tests. Each provider migration instantiates
-- this shape in its own schema.
CREATE TABLE provider.managed_collectors (
  connector_name TEXT,
  region TEXT,
  network_id TEXT,
  kind TEXT,
  mode TEXT,
  origin TEXT,
  adopted_at TIMESTAMPTZ,
  idle_since TIMESTAMPTZ,
  first_ready_at TIMESTAMPTZ,
  collector_id TEXT,
  credential_ref TEXT,
  active_credential_id TEXT,
  workload_ref TEXT,
  revision_ref TEXT,
  runtime_ref TEXT,
  frontend_ref TEXT,
  backend_refs JSONB,
  ingress_ref TEXT,
  placement_refs JSONB,
  endpoint_grpc TEXT,
  endpoint_http TEXT,
  endpoint_source TEXT,
  tls_mode TEXT,
  tls_termination TEXT,
  ingress_tier TEXT,
  image_digest TEXT,
  image_tag TEXT,
  image_arch TEXT,
  license_secret_ref TEXT,
  license_expires_at TIMESTAMPTZ,
  config_hash TEXT,
  applied_config_hash TEXT,
  config_pushed_at TIMESTAMPTZ,
  scaling_mode TEXT,
  desired_count INTEGER,
  running_count INTEGER,
  min_count INTEGER,
  max_count INTEGER,
  cpu TEXT,
  memory TEXT,
  opamp_instance_uid TEXT,
  opamp_connected_at TIMESTAMPTZ,
  opamp_last_seen_at TIMESTAMPTZ,
  agent_health TEXT,
  status TEXT,
  message TEXT,
  created_at TIMESTAMPTZ,
  updated_at TIMESTAMPTZ
);
